#include <format>
#include <iomanip>
#include <ios>
#include <iostream>

class FormatGuard {
public:
    explicit FormatGuard(std::ostream& stream)
        : stream_(stream),
          flags_(stream.flags()),
          fill_(stream.fill()),
          precision_(stream.precision()) {}

    ~FormatGuard() {
        stream_.flags(flags_);
        stream_.fill(fill_);
        stream_.precision(precision_);
    }

    FormatGuard(const FormatGuard&) = delete;
    FormatGuard& operator=(const FormatGuard&) = delete;

private:
    std::ostream& stream_;
    std::ios_base::fmtflags flags_;
    char fill_;
    std::streamsize precision_;
};

void print_id_hex(int order_id) {
    FormatGuard guard{std::cout};
    std::cout << std::hex << std::setw(8) << std::setfill('0')
              << order_id << '\n';
}  // flags, fill and precision restored here

void print_id_hex_modern(int order_id) {
    // Self-contained: nothing to save, nothing to restore.
    std::cout << std::format("{:08x}\n", order_id);
}

