struct Tick {
    long sequence;
    double price;
};

namespace {

template<class T>
bool parse_field(std::string_view field, T& out) {
    const char* first = field.data();
    const char* last = field.data() + field.size();
    auto [next, error] = std::from_chars(first, last, out);
    return error == std::errc{} && next == last;
}

}  // namespace

std::vector<Tick> parse_ticks(std::istream& input) {
    std::vector<Tick> ticks;
    std::string line;

    while (std::getline(input, line)) {
        std::string_view view{line};
        std::size_t comma = view.find(',');
        if (comma == std::string_view::npos) {
            continue;
        }

        Tick tick{};
        if (parse_field(view.substr(0, comma), tick.sequence) &&
            parse_field(view.substr(comma + 1), tick.price)) {
            ticks.push_back(tick);
        }
    }
    return ticks;
}

#include <format>
#include <string_view>

struct Order {
    std::string_view symbol;
    double price;
    int quantity;
};

template<>
struct std::formatter<Order> {
    constexpr auto parse(std::format_parse_context& context) {
        return context.begin();  // no custom specification accepted
    }

    auto format(const Order& order, std::format_context& context) const {
        return std::format_to(context.out(), "{} {:.2f}@{}",
                              order.symbol, order.price, order.quantity);
    }
};

#include <array>
#include <cstddef>
#include <format>
#include <optional>
#include <string_view>

struct LogLine {
    std::array<char, 128> bytes;
    std::size_t size;
};

std::optional<LogLine> make_fill_line(std::string_view symbol,
                                      int quantity,
                                      double price) {
    LogLine line{};
    auto result = std::format_to_n(
        line.bytes.begin(), line.bytes.size(),
        "fill symbol={} quantity={} price={:.2f}\n",
        symbol, quantity, price);

    if (result.size > static_cast<std::ptrdiff_t>(line.bytes.size())) {
        return std::nullopt;  // complete record did not fit
    }

    line.size = static_cast<std::size_t>(result.out - line.bytes.begin());
    return line;
}

#include <istream>
#include <string>
#include <vector>

struct PriceScan {
    std::vector<double> prices;
    int skipped = 0;
};

PriceScan read_prices(std::istream& input) {
    PriceScan scan;
    double price = 0.0;

    for (;;) {
        while (input >> price) {
            scan.prices.push_back(price);
        }

        if (input.eof()) {
            break;  // clean exhaustion
        }

        // failbit: the offending characters are still queued.
        input.clear();
        std::string bad_token;
        if (!(input >> bad_token)) {
            break;  // could not even read a token; give up
        }
        ++scan.skipped;
    }
    return scan;
}

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <format>
#include <span>
#include <string>
#include <vector>

struct LogEvent {
    std::chrono::steady_clock::time_point timestamp;
    std::uint32_t site;
    double price;
    std::uint32_t quantity;
};

class EventBuffer {
public:
    explicit EventBuffer(std::size_t capacity) : slots_(capacity) {}

    bool log_event(std::uint32_t site, double price,
                   std::uint32_t quantity) noexcept {
        if (size_ == slots_.size()) {
            return false;  // explicit loss policy, not silent growth
        }
        slots_[size_++] = {std::chrono::steady_clock::now(), site,
                           price, quantity};
        return true;
    }

    std::span<const LogEvent> events() const noexcept {
        return {slots_.data(), size_};
    }

private:
    std::vector<LogEvent> slots_;
    std::size_t size_ = 0;
};

void drain(const EventBuffer& buffer, std::FILE* output) {
    for (const LogEvent& event : buffer.events()) {
        std::string line = std::format(
            "site={} price={:.2f} quantity={}\n",
            event.site, event.price, event.quantity);
        std::fwrite(line.data(), 1, line.size(), output);
    }
}
